svg.script:
(function () {
  // 独立打开时 documentElement 就是这张卡；被内联进 HTML 时得靠 ownerSVGElement 找回自己。
  var svg = (document.currentScript && document.currentScript.ownerSVGElement) || document.getElementById('pelican-card');
  if (!svg) return;

  var PRESETS = [
    { bg: '#ffffff', sky1: '#dceffb', sky2: '#f8fcff', ground: '#e7eef5', ink: '#22303f', accent: '#f0a23c', star: 0 },
    { bg: '#ffffff', sky1: '#d8f5e9', sky2: '#f4fdf9', ground: '#dcf0e5', ink: '#1b3a2e', accent: '#2da44e', star: 0 },
    { bg: '#fffaf5', sky1: '#ffd9b3', sky2: '#fff2e6', ground: '#f2dcc6', ink: '#4a2c1c', accent: '#e2603c', star: 0 },
    { bg: '#171d2a', sky1: '#161c2b', sky2: '#2b3552', ground: '#1e2636', ink: '#e9eff8', accent: '#8ab4ff', star: 1 },
    { bg: '#ffffff', sky1: '#e9e1ff', sky2: '#f8f6ff', ground: '#e4dcf8', ink: '#332a56', accent: '#8250df', star: 0 },
    { bg: '#ffffff', sky1: '#eef1f4', sky2: '#fbfcfd', ground: '#e6eaee', ink: '#14161a', accent: '#2f3742', star: 0 }
  ];
  var KEYS = ['bg', 'sky1', 'sky2', 'ground', 'ink', 'accent', 'star'];

  function applyTheme(p) {
    KEYS.forEach(function (k) { svg.style.setProperty('--' + k, p[k]); });
  }

  // ---- 色块：点一下就换整套配色 ----
  // 选中态 / 悬停 / 张嘴 / 提速线统一用内联 style 落地，只留「初始态 + 过渡曲线」在样式表里：
  // 状态写在元素自己身上，就不必去猜层叠优先级和祖先选择器在这份文档里的解析结果——
  // 这张卡既要能独立打开，也要能被内联进 HTML，两条路径的行为必须一模一样。
  var sws = [].slice.call(svg.querySelectorAll('.sw'));
  var custom = svg.querySelector('#pelican-custom');
  function markSwatch(i) {
    sws.forEach(function (s) {
      var on = +s.dataset.i === i;
      s.setAttribute('aria-pressed', String(on));
      var ring = s.querySelector('.ring');
      if (ring) ring.style.opacity = on ? '1' : '0';
    });
  }
  function pick(i) {
    var p = PRESETS[i];
    if (!p) return;
    applyTheme(p);
    markSwatch(i);
    if (custom) custom.value = p.accent;
  }
  sws.forEach(function (s) {
    var go = function () { pick(+s.dataset.i); };
    s.addEventListener('click', go);
    s.addEventListener('keydown', function (e) {
      if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); go(); }
    });
    s.addEventListener('mouseenter', function () {
      [].slice.call(s.querySelectorAll('.chip')).forEach(function (c) { c.style.transform = 'translateY(-4px)'; });
    });
    s.addEventListener('mouseleave', function () {
      [].slice.call(s.querySelectorAll('.chip')).forEach(function (c) { c.style.transform = ''; });
    });
  });
  markSwatch(0);
  svg.ownerDocument.addEventListener('keydown', function (e) {
    var n = +e.key;
    if (n >= 1 && n <= PRESETS.length) pick(n - 1);
  });

  // ---- 自定义取色：给一个色，推出一整套（天空 / 地面 / 墨 / 底）----
  // 只换 accent 会得到「一张蓝卡配橙鸟」的怪结果，所以这里按色相推导其余变量：
  // 天空取同色相的高明度低饱和，墨色取同色相的极深/极浅，整体才像一套。
  function hexToHsl(hex) {
    var r = parseInt(hex.slice(1, 3), 16) / 255, g = parseInt(hex.slice(3, 5), 16) / 255, b = parseInt(hex.slice(5, 7), 16) / 255;
    var mx = Math.max(r, g, b), mn = Math.min(r, g, b), d = mx - mn, l = (mx + mn) / 2;
    var sat = d === 0 ? 0 : d / (1 - Math.abs(2 * l - 1));
    var h = 0;
    if (d !== 0) {
      if (mx === r) h = 60 * (((g - b) / d) % 6);
      else if (mx === g) h = 60 * ((b - r) / d + 2);
      else h = 60 * ((r - g) / d + 4);
    }
    return [h < 0 ? h + 360 : h, sat, l];
  }
  function hslHex(h, sat, l) {
    var c = (1 - Math.abs(2 * l - 1)) * sat, x = c * (1 - Math.abs(((h / 60) % 2) - 1)), m = l - c / 2;
    var v = h < 60 ? [c, x, 0] : h < 120 ? [x, c, 0] : h < 180 ? [0, c, x] : h < 240 ? [0, x, c] : h < 300 ? [x, 0, c] : [c, 0, x];
    return '#' + v.map(function (n) { return Math.round((n + m) * 255).toString(16).padStart(2, '0'); }).join('');
  }
  function applyCustom(hex) {
    var hsl = hexToHsl(hex), h = hsl[0], dark = hsl[2] < 0.35;
    svg.style.setProperty('--accent', hex);
    svg.style.setProperty('--sky1', hslHex(h, Math.min(hsl[1], 0.5), dark ? 0.14 : 0.87));
    svg.style.setProperty('--sky2', hslHex(h, Math.min(hsl[1], 0.3), dark ? 0.24 : 0.97));
    svg.style.setProperty('--ground', hslHex(h, Math.min(hsl[1], 0.26), dark ? 0.19 : 0.9));
    svg.style.setProperty('--ink', hslHex(h, 0.28, dark ? 0.92 : 0.17));
    svg.style.setProperty('--bg', dark ? hslHex(h, 0.24, 0.11) : '#ffffff');
    svg.style.setProperty('--star', dark ? 1 : 0);
    markSwatch(-1);
  }
  if (custom) custom.addEventListener('input', function () { applyCustom(custom.value); });

  // ---- 踏频：SMIL 没有「速度」概念，改所有动画的 dur 就是改速度 ----
  var speed = svg.querySelector('#pelican-speed');
  var speedLines = svg.querySelector('.speed-lines');
  function setSpeed(mult) {
    if (speedLines) speedLines.style.opacity = mult >= 1.6 ? '1' : '0';
    // 只调传动系（轮 / 腿 / 曲柄 / 地面滚动）：天空的云和太阳是环境，不该跟着变
    var list = svg.querySelectorAll('animate, animateTransform');
    for (var i = 0; i < list.length; i++) {
      var a = list[i];
      if (a.getAttribute('data-ambient')) continue;
      if (!a.dataset.base) a.dataset.base = String(parseFloat(a.getAttribute('dur')) || 1.6);
      a.setAttribute('dur', (parseFloat(a.dataset.base) / mult).toFixed(3) + 's');
    }
  }
  if (speed) speed.addEventListener('input', function () { setSpeed(parseFloat(speed.value)); });

  // ---- 点鹈鹕：张嘴叫一声（气泡 + 喙下摆）----
  var rig = svg.querySelector('#pelican-rig');
  var bubble = svg.querySelector('.bubble');
  var beak = svg.querySelector('.beak');
  var timer = null;
  function honk() {
    if (bubble) {
      bubble.style.opacity = '1';
      bubble.style.transform = 'translateY(-14px)';
    }
    if (beak && beak.animate) {
      beak.animate(
        [{ transform: 'rotate(0deg)' }, { transform: 'rotate(14deg)' }, { transform: 'rotate(0deg)' }],
        { duration: 420, iterations: 2, easing: 'ease-in-out' }
      );
    }
    clearTimeout(timer);
    timer = setTimeout(function () {
      if (bubble) {
        bubble.style.opacity = '0';
        bubble.style.transform = '';
      }
    }, 1300);
  }
  if (rig) rig.addEventListener('click', honk);
})();
